const VerifyRequest = (function () {
  const module = { exports: {} };
  /**
   * verify-request: التحقق من طلب التطبيق قبل أي عمل (عقد n8n، الإصدار v1).
   *
   * دالة نقية: لا شبكة ولا ساعة ولا حالة عامة. الوقت والحالة يُمرَّران ويُعادان.
   * تُضمَّن هذه الشيفرة حرفيًّا في عقدة Code، ويستوردها vitest كما هي.
   * لا استيراد إلا `crypto` المدمجة (NODE_FUNCTION_ALLOW_BUILTIN=crypto).
   *
   * التوقيع المتوقَّع (من العقد):
   *   X-Nx-Sig = "v1=" + hex(HMAC-SHA256(secret,
   *     "nx-n8n:v1|" + ts + "|" + nonce + "|" + path + "|" + sha256hex(body)))
   *
   * الرفض (كلّه يعود 200 مع code=auth_failed من العقدة التي تبني الغلاف):
   *   - انحراف الساعة أكثر من 30 ثانية
   *   - نونس مكرَّر خلال 120 ثانية (السقف 5000 مدخل)
   *   - بصمة المتن أو التوقيع لا يطابق
   *
   * ترتيب الفحوص مقصود: التوقيع أولًا ثم التكرار. النونس لا يُسجَّل إلا بعد
   * توقيع صحيح، وإلا ملأ مهاجمٌ بلا مفتاح مخزن النونس وطرد نونسات حقيقية.
   *
   * المتن: العقدة الأصلية تمرّر المتن الخام (base64) إن توفّر، وإلا يُعاد تسلسل
   * المتن المحلَّل بـJSON.stringify. المسار الثاني مكافئ دلاليًّا لما سيُعالَج،
   * ويطابق ما يُرسله التطبيق إن بُني المتن بـJSON.stringify. لم يُقَس على n8n حقيقي.
   */
  const crypto = require("crypto");

  const KEY_ID = "v1";
  const SKEW_MS = 30000;
  const NONCE_TTL_MS = 120000;
  const NONCE_CAP = 5000;
  const MIN_SECRET_LENGTH = 32;
  const NONCE_RE = /^[0-9a-f]{32}$/;
  const SIG_RE = /^v1=[0-9a-f]{64}$/;
  const TS_RE = /^[0-9]{1,12}$/;
  const MAX_DEADLINE_MS = 120000;

  function sha256hex(text) {
    return crypto.createHash("sha256").update(String(text), "utf8").digest("hex");
  }

  function hmacHex(secret, text) {
    return crypto.createHmac("sha256", secret).update(String(text), "utf8").digest("hex");
  }

  function headerValue(headers, name) {
    if (!headers || typeof headers !== "object") return "";
    const wanted = String(name).toLowerCase();
    for (const key of Object.keys(headers)) {
      if (key.toLowerCase() === wanted) {
        const value = Array.isArray(headers[key]) ? headers[key][0] : headers[key];
        return typeof value === "string" ? value.trim() : "";
      }
    }
    return "";
  }

  function constantTimeEqual(a, b) {
    const left = Buffer.from(String(a), "utf8");
    const right = Buffer.from(String(b), "utf8");
    if (left.length !== right.length) return false;
    return crypto.timingSafeEqual(left, right);
  }

  /** يُسقط المنتهي ويعيد نسخة جديدة؛ لا يعدّل المدخل. */
  function pruneNonces(store, now) {
    const next = {};
    if (!store || typeof store !== "object") return next;
    for (const key of Object.keys(store)) {
      const expiresAt = store[key];
      if (typeof expiresAt === "number" && expiresAt > now && NONCE_RE.test(key)) {
        next[key] = expiresAt;
      }
    }
    return next;
  }

  /** يضيف نونسًا ويطرد الأقدم عند بلوغ السقف. يعيد المخزن الجديد وعدد المطرودين. */
  function rememberNonce(store, nonce, now) {
    const next = pruneNonces(store, now);
    let evicted = 0;
    const keys = Object.keys(next);
    if (keys.length >= NONCE_CAP) {
      keys.sort((a, b) => next[a] - next[b]);
      const drop = keys.length - NONCE_CAP + 1;
      for (let i = 0; i < drop; i += 1) {
        delete next[keys[i]];
        evicted += 1;
      }
    }
    next[nonce] = now + NONCE_TTL_MS;
    return { store: next, evicted };
  }

  function canonicalText(body) {
    const text = JSON.stringify(body);
    return typeof text === "string" ? text : "";
  }

  /**
   * المتن الخام يُقبل مرشَّحًا فقط إن كان JSON يطابق المتن المحلَّل دلاليًّا.
   * في نمط التخزين على القرص قد يحمل الحقل معرّفًا لا محتوى، فيسقط هنا بدل أن
   * يُرفض كل طلب سليم.
   */
  function rawCandidate(rawBodyBase64, body) {
    if (typeof rawBodyBase64 !== "string" || rawBodyBase64.length === 0) return null;
    try {
      const text = Buffer.from(rawBodyBase64, "base64").toString("utf8");
      if (JSON.stringify(JSON.parse(text)) !== canonicalText(body)) return null;
      return text;
    } catch (error) {
      return null;
    }
  }

  function fail(reason, nonces) {
    return {
      ok: false,
      code: reason === "no_secret" ? "internal" : "auth_failed",
      reason,
      nonces,
      nonce: "",
      ts: 0,
      deadlineMs: null,
      bodySource: "",
      evicted: 0,
    };
  }

  /**
   * @param {object} input
   * @param {object} input.headers رؤوس الطلب (أي حالة أحرف)
   * @param {*} input.body المتن المحلَّل
   * @param {string} [input.rawBodyBase64] المتن الخام إن توفّر
   * @param {string} input.path المسار المغلق لهذا الـworkflow (ثابت لا من الطلب)
   * @param {string} input.secret السر (32 حرفًا فأكثر)
   * @param {number} input.now الوقت بالميللي ثانية
   * @param {object} [input.nonces] مخزن النونس {nonce: expiresAtMs}
   */
  function evaluate(input) {
    const now =
      input && typeof input.now === "number" && isFinite(input.now) ? input.now : Date.now();
    let nonces = pruneNonces(input && input.nonces, now);
    try {
      // السرّ يُقصّ من الفراغات والأسطر حول طرفيه كما يفعل التطبيق (`parseSecret` في config.server.ts):
      // سطرٌ ختاميّ ملصوق مع السرّ في أحد الطرفين كان يُسقط كل طلب بصمت (توقيعان لسرّين مختلفين).
      const rawSecret = input && input.secret;
      const secret = typeof rawSecret === "string" ? rawSecret.trim() : rawSecret;
      if (typeof secret !== "string" || secret.length < MIN_SECRET_LENGTH) {
        return fail("no_secret", nonces);
      }
      const path = input && typeof input.path === "string" ? input.path : "";
      if (!path) return fail("bad_path", nonces);

      const headers = input.headers;
      if (headerValue(headers, "x-nx-key-id") !== KEY_ID) return fail("bad_key_id", nonces);

      const tsText = headerValue(headers, "x-nx-ts");
      if (!TS_RE.test(tsText)) return fail("bad_ts", nonces);
      const ts = Number(tsText);
      // بالثواني الكاملة كما يفعل التطبيق (`verifyRequestSignature`): الختم ثوانٍ صحيحة، ومقارنته بالمللي ثانية
      // كانت ترفض ما يقبله التطبيق في الثانية التي تلي الثلاثين (ساعة n8n متقدّمة 30.0 إلى 30.999 ث).
      if (Math.abs(Math.floor(now / 1000) - ts) > SKEW_MS / 1000) return fail("skew", nonces);

      const nonce = headerValue(headers, "x-nx-nonce").toLowerCase();
      if (!NONCE_RE.test(nonce)) return fail("bad_nonce", nonces);

      const signature = headerValue(headers, "x-nx-sig").toLowerCase();
      if (!SIG_RE.test(signature)) return fail("bad_signature_format", nonces);

      const candidates = [];
      const raw = rawCandidate(input.rawBodyBase64, input.body);
      if (raw !== null) candidates.push({ source: "raw", text: raw });
      candidates.push({ source: "canonical", text: canonicalText(input.body) });

      let matched = "";
      for (const candidate of candidates) {
        const expected =
          "v1=" +
          hmacHex(
            secret,
            "nx-n8n:v1|" + ts + "|" + nonce + "|" + path + "|" + sha256hex(candidate.text),
          );
        if (constantTimeEqual(expected, signature) && matched === "") matched = candidate.source;
      }
      if (matched === "") return fail("bad_signature", nonces);

      if (nonces[nonce] !== undefined) return fail("replay", nonces);
      const remembered = rememberNonce(nonces, nonce, now);
      nonces = remembered.store;

      const deadlineText = headerValue(headers, "x-nx-deadline-ms");
      let deadlineMs = null;
      if (/^[0-9]{1,6}$/.test(deadlineText)) {
        const parsed = Number(deadlineText);
        if (parsed >= 1 && parsed <= MAX_DEADLINE_MS) deadlineMs = parsed;
      }

      return {
        ok: true,
        code: "ok",
        reason: "",
        nonces,
        nonce,
        ts,
        deadlineMs,
        bodySource: matched,
        evicted: remembered.evicted,
      };
    } catch (error) {
      return fail("exception", nonces);
    }
  }

  const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

  /**
   * النونس ومعرّف الطلب «كما ادّعاهما المرسل»، بصرف النظر عن صحة التوقيع. يُوقَّع بهما
   * ردّ الفشل ليقرأ التطبيق auth_failed بدل أن يُسقطه. ليسا موثوقين ولا يُستعملان
   * قرارًا: النونس هنا لا يُسجَّل، وإنما يوقَّع به الجواب فقط.
   */
  function claimedContext(input) {
    const out = { nonce: "", requestId: "" };
    try {
      const nonce = headerValue(input && input.headers, "x-nx-nonce").toLowerCase();
      if (NONCE_RE.test(nonce)) out.nonce = nonce;
      const body = input && input.body;
      if (body && typeof body === "object" && UUID_RE.test(String(body.requestId))) {
        out.requestId = body.requestId;
      }
    } catch (error) {
      // يبقى فارغًا
    }
    return out;
  }

  function verifyRequest(input) {
    const result = evaluate(input);
    const claimed = claimedContext(input);
    result.claimedNonce = claimed.nonce;
    result.claimedRequestId = claimed.requestId;
    return result;
  }

  if (typeof module !== "undefined" && module.exports) {
    module.exports = {
      verifyRequest,
      rememberNonce,
      pruneNonces,
      sha256hex,
      hmacHex,
      SKEW_MS,
      NONCE_TTL_MS,
      NONCE_CAP,
      MIN_SECRET_LENGTH,
    };
  }
  return module.exports;
})();

const sd = $getWorkflowStaticData("global");
const item = $input.first();
const webhook = item.json || {};
const rawB64 =
  item.binary && item.binary.data && typeof item.binary.data.data === "string"
    ? item.binary.data.data
    : undefined;
const now = Date.now();
const v = VerifyRequest.verifyRequest({
  headers: webhook.headers,
  body: webhook.body,
  rawBodyBase64: rawB64,
  path: "fnn-runner-v1",
  secret: $env.FINN_N8N_SECRET,
  now,
  nonces: sd.nonces,
});
sd.nonces = v.nonces;
return [
  {
    json: {
      ok: v.ok,
      code: v.code,
      reason: v.reason,
      ctx: { requestId: v.claimedRequestId, nonce: v.claimedNonce, t0: now, deadlineMs: v.deadlineMs },
      body: webhook.body,
    },
  },
];

const Budget = (function () {
  const module = { exports: {} };
  /**
   * budget: سقف الطلبات العام (60 طلبًا في الدقيقة لكل workflow) بنافذة منزلقة.
   *
   * نقية: الحالة والوقت يُمرَّران، والحالة الجديدة تُعاد (تُحفظ في static data).
   * تُستدعى بعد التحقق من التوقيع، فطلب مجهول لا يستهلك الميزانية.
   *
   * الحالة التالفة (ليست كائنًا، أو hits ليست مصفوفة أرقام) تُصفَّر ويُسمح
   * بالطلب: عطل الحالة لا يجوز أن يحجب خدمة سليمة. الطلب المرفوض لا يُسجَّل.
   * السقف الفعلي لا يتجاوز `limit` مدخلًا في الحالة، فلا تنمو بلا حدّ.
   */
  const DEFAULT_LIMIT = 60;
  const DEFAULT_WINDOW_MS = 60000;

  /**
   * @param {object} input
   * @param {{hits?: number[]}} [input.state]
   * @param {number} input.now
   * @param {number} [input.limit]
   * @param {number} [input.windowMs]
   * @returns {{allowed: boolean, state: {hits: number[]}, remaining: number, retryAfterMs: number}}
   */
  function checkBudget(input) {
    const now =
      input && typeof input.now === "number" && isFinite(input.now) ? input.now : Date.now();
    const limit =
      input && Number.isInteger(input.limit) && input.limit > 0 ? input.limit : DEFAULT_LIMIT;
    const windowMs =
      input && Number.isInteger(input.windowMs) && input.windowMs > 0
        ? input.windowMs
        : DEFAULT_WINDOW_MS;
    const previous = input && input.state && Array.isArray(input.state.hits) ? input.state.hits : [];
    const hits = previous
      .filter((t) => typeof t === "number" && isFinite(t) && t <= now && now - t < windowMs)
      .sort((a, b) => a - b)
      .slice(-limit);
    if (hits.length >= limit) {
      const retryAfterMs = Math.max(1, hits[0] + windowMs - now);
      return { allowed: false, state: { hits }, remaining: 0, retryAfterMs };
    }
    hits.push(now);
    return { allowed: true, state: { hits }, remaining: limit - hits.length, retryAfterMs: 0 };
  }

  if (typeof module !== "undefined" && module.exports) {
    module.exports = { checkBudget, DEFAULT_LIMIT, DEFAULT_WINDOW_MS };
  }
  return module.exports;
})();

const sd = $getWorkflowStaticData("global");
const j = $input.first().json;
const r = Budget.checkBudget({ state: sd.budget, now: Date.now() });
sd.budget = r.state;
const out = Object.assign({}, j, { budgetOk: r.allowed });
if (!r.allowed) out.code = "budget_exhausted";
return [{ json: out }];

const RunnerDispatch = (function () {
  const module = { exports: {} };
  /**
   * runner-dispatch: بوّابة مشغّل الأتمتة (FNN) على كتالوج مغلق من خمسة معرّفات.
   *
   * الكتالوج لا يُؤخذ من الطلب ولا يُوسَّع بمعلمة. كل معرّف يؤدي عملًا غير ضار:
   *   engineering_digest        ملخص تنبيهات أمنية عامة (قراءة API عامّ)
   *   dependency_advisory_scan  تنبيهات عامة على حزم رئيسية بالاسم (ليست تدقيقًا
   *                             لنسخ المثبّتة؛ هي تنبيهات منشورة حديثًا على هذه الأسماء)
   *   research_cache_purge      تنظيف مفتاح researchCache من static data فقط
   *   canary_run_now            فحص صحة فوري بلا تغيير حالة المراقب
   *   owner_notify_test         رسالة اختبار إلى قناة المالك
   * لا نشر ولا مستودع ولا كتابة في جداول معرفة أو قواعد بيانات. التنفيذ كلّه إما
   * قراءة عامة أو تنظيف حالة n8n نفسها.
   *
   * المعلمات: أعداد صحيحة ضمن حدود وقيم من قوائم فقط؛ أي مفتاح غير معروف يُرفض.
   * التكرار: مفتاح الـIdempotency-Key (نونس التأكيد) يحفظ النتيجة 24 ساعة،
   * والمكرَّر يعود already_done بالنتيجة المحفوظة. المخزن بسقف 500 مدخل.
   *
   * نقية: الحالة والوقت يُمرَّران ويُعادان. لا شبكة هنا.
   */
  const CATALOG = [
    "engineering_digest",
    "dependency_advisory_scan",
    "research_cache_purge",
    "canary_run_now",
    "owner_notify_test",
  ];
  const IDEMPOTENCY_TTL_MS = 24 * 3600 * 1000;
  const IDEMPOTENCY_CAP = 500;
  const SCAN_PACKAGES = [
    "react",
    "vite",
    "zod",
    "ai",
    "@supabase/supabase-js",
    "@tanstack/react-router",
  ];
  const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  const IDEM_RE = /^[A-Za-z0-9._:-]{8,128}$/;

  const PARAM_SPECS = {
    engineering_digest: {
      days: { type: "int", min: 1, max: 30, fallback: 7 },
      severity: { type: "enum", values: ["critical", "high"], fallback: "critical" },
    },
    dependency_advisory_scan: {
      days: { type: "int", min: 1, max: 90, fallback: 30 },
    },
    research_cache_purge: {
      scope: { type: "enum", values: ["expired", "all"], fallback: "expired" },
    },
    canary_run_now: {},
    owner_notify_test: {},
  };

  function isPlainObject(value) {
    return value !== null && typeof value === "object" && !Array.isArray(value);
  }

  /** يتحقق من المعلمات ويملأ الافتراضات. يعيد {ok, params}. */
  function validateParams(workflow, params) {
    const spec = Object.prototype.hasOwnProperty.call(PARAM_SPECS, workflow)
      ? PARAM_SPECS[workflow]
      : null;
    if (!spec) return { ok: false };
    const input = params === undefined ? {} : params;
    if (!isPlainObject(input)) return { ok: false };
    for (const key of Object.keys(input)) {
      if (!Object.prototype.hasOwnProperty.call(spec, key)) return { ok: false };
    }
    const out = {};
    for (const key of Object.keys(spec)) {
      const rule = spec[key];
      const value = input[key];
      if (value === undefined) {
        out[key] = rule.fallback;
      } else if (rule.type === "int") {
        if (!Number.isInteger(value) || value < rule.min || value > rule.max) return { ok: false };
        out[key] = value;
      } else {
        if (rule.values.indexOf(value) === -1) return { ok: false };
        out[key] = value;
      }
    }
    return { ok: true, params: out };
  }

  function pruneStore(store, now) {
    const next = {};
    if (!isPlainObject(store)) return next;
    for (const key of Object.keys(store)) {
      const entry = store[key];
      if (
        isPlainObject(entry) &&
        typeof entry.at === "number" &&
        now - entry.at < IDEMPOTENCY_TTL_MS
      ) {
        next[key] = entry;
      }
    }
    return next;
  }

  /**
   * @param {object} input {body, idemKey, now, store}
   * @returns {{decision: string, workflow: string, params: object|null, requestId: string,
   *   idemKey: string, result: object|null, store: object}}
   */
  function dispatch(input) {
    const now =
      input && typeof input.now === "number" && isFinite(input.now) ? input.now : Date.now();
    const store = pruneStore(input && input.store, now);
    const base = { workflow: "", params: null, requestId: "", idemKey: "", result: null, store };
    const body = input && input.body;
    if (!isPlainObject(body) || body.v !== 1)
      return Object.assign({}, base, { decision: "bad_params" });
    const requestId =
      typeof body.requestId === "string" && UUID_RE.test(body.requestId) ? body.requestId : "";
    if (!requestId) return Object.assign({}, base, { decision: "bad_params" });
    base.requestId = requestId;
    const idemKey = input && typeof input.idemKey === "string" ? input.idemKey.trim() : "";
    if (!IDEM_RE.test(idemKey)) return Object.assign({}, base, { decision: "bad_params" });
    base.idemKey = idemKey;
    if (typeof body.workflow !== "string" || CATALOG.indexOf(body.workflow) === -1) {
      return Object.assign({}, base, { decision: "unknown_workflow" });
    }
    base.workflow = body.workflow;
    const checked = validateParams(body.workflow, body.params);
    if (!checked.ok) return Object.assign({}, base, { decision: "bad_params" });
    base.params = checked.params;
    const seen = store[idemKey];
    if (seen) {
      if (seen.workflow !== body.workflow) return Object.assign({}, base, { decision: "bad_params" });
      return Object.assign({}, base, { decision: "already_done", result: seen.result });
    }
    return Object.assign({}, base, { decision: "run" });
  }

  /** يحفظ نتيجة تنفيذ ناجح تحت مفتاح التكرار. */
  function recordResult(input) {
    const now =
      input && typeof input.now === "number" && isFinite(input.now) ? input.now : Date.now();
    const store = pruneStore(input && input.store, now);
    store[input.idemKey] = { at: now, workflow: input.workflow, result: input.result };
    const keys = Object.keys(store);
    if (keys.length > IDEMPOTENCY_CAP) {
      keys.sort((a, b) => store[a].at - store[b].at);
      for (const key of keys.slice(0, keys.length - IDEMPOTENCY_CAP)) delete store[key];
    }
    return store;
  }

  function sinceDate(now, days) {
    return new Date(now - days * 86400000).toISOString().slice(0, 10);
  }

  /** طلب GET عام لكل معرّف يحتاج API: يعيد {url, headers} أو null. */
  function buildRequest(workflow, params, now, stubBase) {
    const root = stubBase
      ? String(stubBase).replace(/\/+$/, "") + "/api.github.com"
      : "https://api.github.com";
    const headers = {
      Accept: "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
      "User-Agent": "nx-n8n-runner",
    };
    if (workflow === "engineering_digest") {
      return {
        url:
          root +
          "/advisories?type=reviewed&ecosystem=npm&severity=" +
          params.severity +
          "&published=" +
          encodeURIComponent(">=" + sinceDate(now, params.days)) +
          "&sort=published&direction=desc&per_page=10",
        headers,
      };
    }
    if (workflow === "dependency_advisory_scan") {
      return {
        url:
          root +
          "/advisories?type=reviewed&ecosystem=npm&affects=" +
